import std.concurrent as conc
import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let ch: conc.Channel<Int64> = conc.channel(1)
    ch.send(7)
    let v = ch.receive()
    let n: Int64 = 5
    match v {
        Some(n) => { let _ = 0 }
        None => { let _ = 0 }
    }
    let r = scope timeout(1000) {
        let t = task effect io {
            let _ = n
        }
        let _ = t.await()
    }
    match r {
        Ok(_) => { io.println("ok") }
        Err(_) => { io.println("timedout") }
    }
    return Ok(())
}
